result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "httpparse.py", "content": """"HTTP/1.1 request parser over raw bytes, stdlib only."""

from typing import Dict, Iterator, List, Optional, Tuple

MAX_REQUEST_LINE = 8192
MAX_HEADERS = 100


class HttpParseError(Exception):
    """Raised on malformed input; str(exc) is a short reason."""


class Headers:
    """Case-insensitive multidict preserving insertion order."""

    def __init__(self) -> None:
        self._pairs: List[Tuple[str, str]] = []

    def add(self, name: str, value: str) -> None:
        self._pairs.append((name, value))

    def getall(self, name: str) -> List[str]:
        lname = name.lower()
        return [v for k, v in self._pairs if k.lower() == lname]

    def get(self, name: str, default: Optional[str] = None) -> Optional[str]:
        vals = self.getall(name)
        return vals[0] if vals else default

    def __getitem__(self, name: str) -> str:
        v = self.get(name)
        if v is None:
            raise KeyError(name)
        return v

    def __contains__(self, name: object) -> bool:
        return isinstance(name, str) and bool(self.getall(name))

    def __len__(self) -> int:
        return len(self._pairs)

    def __iter__(self) -> Iterator[Tuple[str, str]]:
        return iter(self._pairs)

    def items(self) -> List[Tuple[str, str]]:
        return list(self._pairs)

    def __repr__(self) -> str:
        return f"Headers({self._pairs!r})"


class Request:
    def __init__(self, method: str, target: str, version: str,
                 headers: Headers, body: bytes) -> None:
        self.method = method
        self.target = target
        self.version = version
        self.headers = headers
        self.body = body

    def __repr__(self) -> str:
        return (f"Request(method={self.method!r}, target={self.target!r}, "
                f"version={self.version!r}, headers={self.headers!r}, "
                f"body={self.body!r})")


def _is_token(s: str) -> bool:
    if not s:
        return False
    # RFC 7230 tchar
    special = "!#$%&'*+-.^_`|~"
    return all(c.isalnum() or c in special for c in s)


class RequestParser:
    """Incremental HTTP/1.1 request parser.

    feed(data) consumes raw bytes. It returns the finished Request if this
    call completed one, otherwise None. Errors raise HttpParseError.
    """

    def __init__(self) -> None:
        self._buf = bytearray()
        self._state = "request_line"  # request_line | headers | body | done
        self._method = ""
        self._target = ""
        self._version = ""
        self._headers = Headers()
        self._content_length: Optional[int] = None
        self._seen_cl_values: List[int] = []
        self._request: Optional[Request] = None

    @property
    def request(self) -> Optional[Request]:
        return self._request

    @property
    def complete(self) -> bool:
        return self._state == "done"

    def feed(self, data: bytes) -> Optional[Request]:
        if self._state == "done":
            raise HttpParseError("already complete")
        self._buf.extend(data)
        try:
            self._consume()
        except HttpParseError:
            self._state = "error"
            raise
        if self._state == "done":
            req = self._request
            self._request = None  # hand off ownership
            return req
        return None

    # -- internals ---------------------------------------------------------

    def _next_line(self, max_len: int, what: str) -> Optional[bytes]:
        """Return one CRLF-terminated line (without CRLF), or None if the
        buffer has no complete line yet. Rejects bare LF."""
        idx = self._buf.find(b"\n")
        if idx == -1:
            if len(self._buf) > max_len:
                raise HttpParseError(f"{what} too long")
            return None
        if idx == 0 or self._buf[idx - 1:idx] != b"\r":
            raise HttpParseError("bare LF line ending")
        line = bytes(self._buf[:idx - 1])
        del self._buf[:idx + 1]
        if len(line) > max_len:
            raise HttpParseError(f"{what} too long")
        return line

    def _consume(self) -> None:
        while True:
            if self._state == "request_line":
                line = self._next_line(MAX_REQUEST_LINE, "request line")
                if line is None:
                    return
                self._parse_request_line(line)
                self._state = "headers"
            elif self._state == "headers":
                line = self._next_line(MAX_HEADERS * 1024, "header")
                if line is None:
                    return
                if line == b"":
                    self._finish_head()
                    self._state = "body" if self._content_length else "done"
                    continue
                if len(self._headers) >= MAX_HEADERS:
                    raise HttpParseError("too many headers")
                self._parse_header(line)
            elif self._state == "body":
                if len(self._buf) < self._content_length:
                    return
                body = bytes(self._buf[:self._content_length])
                del self._buf[:self._content_length]
                self._request = Request(
                    self._method, self._target, self._version,
                    self._headers, body)
                self._state = "done"
                return
            else:  # done
                return

    def _parse_request_line(self, line: bytes) -> None:
        try:
            text = line.decode("ascii")
        except UnicodeDecodeError:
            raise HttpParseError("non-ASCII in request line")
        parts = text.split(" ")
        if len(parts) != 3:
            raise HttpParseError("malformed request line")
        method, target, version = parts
        if not _is_token(method):
            raise HttpParseError("bad method")
        if not target or " " in target:
            raise HttpParseError("bad request target")
        if version != "HTTP/1.1":
            raise HttpParseError("unsupported HTTP version")
        self._method, self._target, self._version = method, target, version

    def _parse_header(self, line: bytes) -> None:
        try:
            text = line.decode("ascii")
        except UnicodeDecodeError:
            raise HttpParseError("non-ASCII in header")
        if text[0] in " \t":
            raise HttpParseError("obsolete line folding (obs-fold)")
        name, sep, value = text.partition(":")
        if not sep:
            raise HttpParseError("header line without colon")
        if not _is_token(name):
            raise HttpParseError("bad header field name")
        self._headers.add(name, value.strip(" \t"))
        if name.lower() == "content-length":
            if not value.strip(" \t").isdigit():
                raise HttpParseError("invalid Content-Length")
            self._seen_cl_values.append(int(value.strip(" \t")))
            if len(set(self._seen_cl_values)) > 1:
                raise HttpParseError("conflicting Content-Length values")
            self._content_length = self._seen_cl_values[0]

    def _finish_head(self) -> None:
        self._content_length = self._seen_cl_values[0] if self._seen_cl_values else 0
